function formatCoord(pointList) {
  var xList = [];
  var yList = [];
  if (isObject(pointList) && pointList.type === 'FeatureCollection') {
    pointList.features.forEach(function (feature) {
      var coord = feature.geometry.coordinates;
      xList.push(coord[0]);
      yList.push(coord[1]);
    });
  } else if (Array.isArray(pointList)) {
    pointList.forEach(function (item) {
      if (item.type === 'Feature') {
        var coord = item.geometry.coordinates;
        xList.push(coord[0]);
        yList.push(coord[1]);
      } else if (Array.isArray(item)) {
        xList.push(item[0]);
        yList.push(item[1]);
      } else if (isObject(item)) {
        xList.push(item.x);
        yList.push(item.y);
      }
    });
  }
  return {
    xList: xList,
    yList: yList
  };
}
